/* ---------- views ---------- */
function show(v, focus){
  if (VIEWS.indexOf(v) < 0) v = 'home';
  if (v === 'checkout' && !(draft && camp(draft.campaign))) v = 'funding';
  if (v === 'paid' && !paidResult) v = 'funding';
  leon.stop(); var pv = document.getElementById('pjVideo'); if (pv) pv.pause();
  view = v;
  $$('.view').forEach(function(s){ s.hidden = s.getAttribute('data-view') !== v; });
  var navv = (v === 'project' || v === 'create') ? 'funding' : v;
  $$('#nav a').forEach(function(a){ if (a.getAttribute('href') === '#' + navv) a.setAttribute('aria-current', 'page'); else a.removeAttribute('aria-current'); });
  $('#nav').classList.remove('is-open'); $('#menuBtn').setAttribute('aria-expanded', 'false');
  window.scrollTo(0, 0);
  if (focus) { var m = $('#main'); m.focus({preventScroll:true}); }
  if (v === 'home') { embers.start(); film.start(); } else { embers.stop(); film.stop(); }
  if (v === 'checkout') renderCheckout();
  if (v === 'paid') renderPaid();
  if (v === 'heroes' && MODE === 'live') fetchHeroes();
}
