function norm(s){ return (s || '').normalize('NFKC').toLowerCase(); }
function heroSource(){ return (MODE === 'live' && remote) ? remote : HEROES; }
function filtered(){
  var q = norm(filt.q.trim());
  return heroSource().filter(function(r){
    if (filt.country !== 'ALL' && r.country !== filt.country) return false;
    if (filt.cat !== 'ALL' && r.cat !== filt.cat) return false;
    if (!q) return true;
    var hay = [r.id, t('country.' + r.country)];
    LANGS.forEach(function(l){ var x = r[l]; if (x) hay.push(x.name, x.place, x.headline, x.story); });
    return norm(hay.join(' ')).indexOf(q) > -1;
  });
}
