/* ---------- forms ---------- */
var RULES = {
  funding: {email:{req:1, email:1}, country:{req:1}, consentPrivacy:{check:1}},
  report: {country:{req:1}, place:{max:120}, heroName:{max:120}, story:{req:1, min:20, max:2000, code:'story'}, src1:{url:1}, src2:{url:1}, src3:{url:1}, photo:{file:1}, relation:{req:1}, reporter:{max:60}, email:{req:1, email:1}, consentPrivacy:{check:1}, consentFact:{check:1}},
  contact: {name:{req:1, max:60}, email:{req:1, email:1}, topic:{req:1}, message:{req:1, min:5, max:3000}, org:{max:100}, consentPrivacy:{check:1}},
  subscribe: {email:{req:1, email:1}, consentPrivacy:{check:1}},
  project: {reportRef:{req:1, re:/^R-\d{6}-[0-9A-F]{6}$/i, code:'notVerified'}, reportEmail:{req:1, email:1}, storyId:{req:1, re:/^OREH-[A-Z]{2}-\d{4}-\d{4}$/i, code:'story404'},
    title:{req:1, max:60}, summary:{req:1, max:100}, category:{req:1}, image:{file:1},
    goal:{req:1, num:[100000, 1000000000]}, price:{req:1, num:[1000, 10000000]}, qty:{req:1, num:[1, 1000000]}, start:{req:1}, days:{req:1, num:[1, 60]},
    rewards:{req:1, max:1000}, story:{req:1, min:50, max:3000, code:'long'}, budget:{req:1, max:1000}, name:{req:1, max:60}, email:{req:1, email:1}, bio:{max:300}, risk:{req:1, max:1000},
    agree:{check:1}, consentPrivacy:{check:1}, pledge:{check:1}, signName:{req:1, max:60, code:'sign'}}
};
if (MODE === 'static') delete RULES.project.reportRef.re; /* reference numbers are issued by reply email for now */
var EMAIL_RE = /^[^\s@<>()",;]{1,64}@[^\s@<>()",;]+\.[^\s@<>()",;]{2,}$/;
function errBox(form, name){ var i = form.elements[name]; return i ? document.getElementById(i.id + '-err') : null; }
function setErr(form, name, code){
  var i = form.elements[name]; var b = errBox(form, name);
  if (i && i.setAttribute) { if (code) i.setAttribute('aria-invalid', 'true'); else i.removeAttribute('aria-invalid'); }
  if (b) b.textContent = code ? t('err.' + code) : '';
}
function clearErrors(form){
  Object.keys(RULES[form.getAttribute('data-form')]).forEach(function(n){ setErr(form, n, null); });
  var st = form.querySelector('.status'); st.hidden = true; st.textContent = '';
}
function validate(form){
  var rules = RULES[form.getAttribute('data-form')]; var first = null; var ok = true;
  Object.keys(rules).forEach(function(n){
    var r = rules[n]; var i = form.elements[n]; if (!i || !i.closest) return;
    var scope = i.closest('[data-track]'); if (scope && scope.hidden) { setErr(form, n, null); return; }
    var code = null;
    if (r.check) { if (!i.checked) code = 'consent'; }
    else if (r.file) {
      var f = i.files && i.files[0];
      if (f && (['image/jpeg','image/png','image/webp'].indexOf(f.type) < 0 || f.size > 5 * 1024 * 1024)) code = 'file';
    } else {
      var v = (i.value || '').trim();
      if (r.req && !v) code = 'required';
      else if (v && r.email && !EMAIL_RE.test(v)) code = 'email';
      else if (v && r.url && !/^https?:\/\/[^\s]{3,}$/i.test(v)) code = 'url';
      else if (v && r.min && v.length < r.min) code = r.code || 'required';
      else if (v && r.max && v.length > r.max) code = r.code || 'long';
      else if (v && r.re && !r.re.test(v)) code = r.code || 'required';
      else if (v && r.num) { var x = Number(v.replace(/[,\s]/g, '')); if (!/^\d+$/.test(v.replace(/[,\s]/g, '')) || x < r.num[0] || x > r.num[1]) code = 'range'; }
      if (code === 'required' && r.code === 'sign') code = 'sign';
    }
    setErr(form, n, code);
    if (code) { ok = false; if (!first) first = i; }
  });
  if (first) first.focus();
  return ok;
}
function status(form, kind, text){ var s = form.querySelector('.status'); s.className = 'status status--' + kind; s.textContent = text; s.hidden = false; }
function onSubmit(e){
  e.preventDefault();
  var form = e.currentTarget; var kind = form.getAttribute('data-form');
  clearErrors(form);
  var okv = validate(form);
  if (kind === 'subscribe') { var ce = $('#sb-countries-err'); ce.textContent = subC.length ? '' : t('err.pickCountry'); if (!subC.length) okv = false; }
  if (!okv) { status(form, 'err', t('err.form')); return; }
  if (MODE === 'static') { mailForm(form, kind); return; }
  if (MODE !== 'live') { status(form, 'ok', t('ok.demo')); return; }
  var btn = form.querySelector('button[type=submit]'); var label = btn.textContent;
  btn.disabled = true; btn.textContent = t('f.sending');
  var fd = new FormData(form); fd.append('lang', lang);
  if (kind === 'subscribe') fd.append('countries', subC.join(','));
  fetch(ENDPOINTS[kind], {method:'POST', body:fd, credentials:'same-origin', headers:{'X-CSRF-Token':CSRF, 'Accept':'application/json'}})
    .then(function(res){ return res.json().catch(function(){ return {}; }).then(function(j){ return {status:res.status, body:j}; }); })
    .then(function(r){
      if (r.status === 200 && r.body.ok) { status(form, 'ok', kind === 'subscribe' ? t('sub.okLive') : t('ok.live', {id:r.body.id})); form.reset(); fillSelects(); syncTrack(); if (window.turnstile) try { window.turnstile.reset(); } catch(x){} return; }
      if (r.status === 422 && r.body.fields) { Object.keys(r.body.fields).forEach(function(n){ if (n === 'countries') $('#sb-countries-err').textContent = t('err.pickCountry'); else setErr(form, n, r.body.fields[n]); }); status(form, 'err', t('err.form')); return; }
      status(form, 'err', t(r.status === 429 ? 'err.rate' : 'err.server'));
    })
    .catch(function(){ status(form, 'err', t('err.server')); })
    .then(function(){ btn.disabled = false; btn.textContent = label; });
}

/* ---------- static hosting: the visitor sends the form by email (nothing is stored on the site) ---------- */
function fieldLabel(form, i){
  if (i.type === 'checkbox' || i.type === 'radio') {
    var lab = i.closest('label'); var own = lab ? lab.textContent.trim() : i.name;
    if (i.type === 'radio') { var fs = i.closest('fieldset'); var lg = fs && fs.querySelector('legend'); return lg ? lg.textContent.trim() : own; }
    return own;
  }
  var l = i.id ? form.querySelector('label[for="' + i.id + '"]') : null;
  return (l ? l.textContent : i.name).trim();
}
function mailBody(form, kind){
  var lines = [], files = [];
  Array.prototype.forEach.call(form.elements, function(i){
    if (!i.name || i.disabled || i.closest('.hp')) return;
    var scope = i.closest('[data-track]'); if (scope && scope.hidden) return;
    var tp = (i.type || '').toLowerCase();
    if (tp === 'submit' || tp === 'button' || tp === 'hidden') return;
    if (tp === 'file') { if (i.files && i.files[0]) files.push(i.files[0].name); return; }
    var v;
    if (tp === 'checkbox') { if (!i.checked) return; v = t('mail.yes'); }
    else if (tp === 'radio') { if (!i.checked) return; var lb = i.closest('label'); v = lb ? lb.textContent.trim() : i.value; }
    else if (i.tagName === 'SELECT') { var o = i.options[i.selectedIndex]; v = o && i.value ? o.textContent.trim() : ''; }
    else v = (i.value || '').trim();
    if (!v) return;
    var k = fieldLabel(form, i).replace(/^\[[^\]]+\]\s*/, '');
    lines.push(v.indexOf('\n') > -1 || v.length > 60 ? '■ ' + k + '\n' + v : '■ ' + k + ': ' + v);
  });
  if (kind === 'subscribe') lines.unshift('■ ' + t('sub.countries') + ': ' + subC.map(function(c){ return c === 'ALL' ? t('sub.all') : t('country.' + c); }).join(', '));
  files.forEach(function(n){ lines.push('■ ' + t('mail.attach', {name: n})); });
  lines.push('', '— ' + t('mail.from', {lang: lang.toUpperCase()}));
  return lines.join('\n');
}
function mailForm(form, kind){
  var subj = t('mail.subj.' + kind); var body = mailBody(form, kind);
  var old = form.querySelector('.mailbox'); if (old) old.remove();
  var box = el('div', 'mailbox'); box.setAttribute('role', 'status');
  box.appendChild(el('p', '', t('mail.ready')));
  box.appendChild(el('p', 'mailbox__to', MAIL_TO));
  var row = el('div', 'mailbox__row');
  var a1 = el('a', 'btn btn--navy btn--sm', t('mail.app'));
  a1.href = 'mailto:' + MAIL_TO + '?subject=' + encodeURIComponent(subj) + '&body=' + encodeURIComponent(body);
  var a2 = el('a', 'btn btn--ghost btn--sm', t('mail.gmail'));
  a2.href = 'https://mail.google.com/mail/?view=cm&fs=1&to=' + encodeURIComponent(MAIL_TO) + '&su=' + encodeURIComponent(subj) + '&body=' + encodeURIComponent(body);
  a2.target = '_blank'; a2.rel = 'noopener noreferrer';
  var b3 = el('button', 'btn btn--ghost btn--sm', t('mail.copy')); b3.type = 'button';
  var msg = el('span', 'copied'); msg.setAttribute('role', 'status');
  b3.addEventListener('click', function(){ copyText(subj + '\n\n' + body, function(){ msg.textContent = t('mail.copied'); }, function(){ msg.textContent = t('share.fail'); }); });
  row.appendChild(a1); row.appendChild(a2); row.appendChild(b3); row.appendChild(msg);
  box.appendChild(row);
  form.querySelector('.status').insertAdjacentElement('afterend', box);
  a1.focus();
}

/* ---------- embers (Leo's flame) ---------- */
var embers = (function(){
  var cv = document.getElementById('embers'); var ctx = cv.getContext('2d');
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var parts = [], raf = 0, w = 0, h = 0, dpr = 1, on = false;
  function size(){ var r = cv.getBoundingClientRect(); dpr = Math.min(2, window.devicePixelRatio || 1); w = r.width; h = r.height; cv.width = Math.round(w * dpr); cv.height = Math.round(h * dpr); ctx.setTransform(dpr,0,0,dpr,0,0); var n = Math.round(Math.min(90, w / 14)); parts = []; for (var i = 0; i < n; i++) parts.push(spawn(true)); }
  function spawn(any){ return {x: Math.random() * w, y: any ? Math.random() * h : h + 10, r: .8 + Math.random() * 2.2, v: .2 + Math.random() * .6, s: Math.random() * 6.28, hue: Math.random() < .75 ? 'gold' : 'red', a: .35 + Math.random() * .5}; }
  function draw(step){
    ctx.clearRect(0,0,w,h);
    for (var i = 0; i < parts.length; i++){
      var p = parts[i];
      if (step) { p.y -= p.v; p.s += .02; p.x += Math.sin(p.s) * .3; if (p.y < -10) parts[i] = p = spawn(false); }
      var fade = Math.max(0, Math.min(1, p.y / h * 1.4));
      var g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.r * 4);
      var c = p.hue === 'gold' ? '244,180,95' : '242,135,110';
      g.addColorStop(0, 'rgba(' + c + ',' + (p.a * fade) + ')'); g.addColorStop(1, 'rgba(' + c + ',0)');
      ctx.fillStyle = g; ctx.beginPath(); ctx.arc(p.x, p.y, p.r * 4, 0, 6.283); ctx.fill();
    }
  }
  function loop(){ draw(true); raf = requestAnimationFrame(loop); }
  function start(){ if (on) return; on = true; size(); if (reduce) { draw(false); return; } loop(); }
  function stop(){ on = false; cancelAnimationFrame(raf); }
  window.addEventListener('resize', function(){ if (on) { size(); if (reduce) draw(false); } });
  document.addEventListener('visibilitychange', function(){ if (document.hidden) { cancelAnimationFrame(raf); } else if (on && !reduce) { cancelAnimationFrame(raf); loop(); } });
  return {start:start, stop:stop};
})();

/* ---------- hero film (autoplays muted and loops on every visit; pause and sound buttons) ---------- */
var film = (function(){
  var v = document.getElementById('heroFilm');
  if (!v) return {start:function(){}, stop:function(){}};
  var playBtn = document.getElementById('filmPlay'), soundBtn = document.getElementById('filmSound');
  var held = false, on = false;
  v.muted = true; v.defaultMuted = true;
  function setKey(b, k){ b.setAttribute('data-i18n', k); b.textContent = t(k); }
  function label(){
    setKey(playBtn, v.paused ? 'hero.film.play' : 'hero.film.pause');
    setKey(soundBtn, v.muted ? 'hero.sound.on' : 'hero.sound.off');
    soundBtn.setAttribute('aria-pressed', String(!v.muted));
  }
  function play(){ var p = v.play(); if (p && p.catch) p.catch(function(){ label(); }); }
  function start(){ on = true; if (!held) play(); label(); }
  function stop(){ on = false; v.pause(); label(); }
  v.addEventListener('canplay', function(){ if (on && !held && v.paused) play(); });
  playBtn.addEventListener('click', function(){ if (v.paused) { held = false; play(); } else { held = true; v.pause(); } label(); });
  soundBtn.addEventListener('click', function(){ v.muted = !v.muted; if (!v.muted && v.paused) { held = false; play(); } label(); });
  v.addEventListener('play', label); v.addEventListener('pause', label); v.addEventListener('volumechange', label);
  document.addEventListener('visibilitychange', function(){ if (document.hidden) v.pause(); else if (on && !held) play(); });
  return {start:start, stop:stop};
})();

/* ---------- crowdfunding back end (Supabase) and payments (Toss Payments) ----------
   Configure with three meta tags in index.html: oreh-api (Supabase project URL), oreh-anon-key and
   oreh-toss-client-key. Left empty, the site runs in preview mode: the whole flow works, nothing is charged. */
var CFG = (function(){
  function m(n){ var e = document.querySelector('meta[name="' + n + '"]'); return e ? (e.getAttribute('content') || '').trim() : ''; }
  return {api: m('oreh-api').replace(/\/+$/, ''), anon: m('oreh-anon-key'), toss: m('oreh-toss-client-key')};
})();
var HAS_API = !!(CFG.api && CFG.anon);
var LIVE_PAY = HAS_API && !!CFG.toss;
var TEST_PAY = LIVE_PAY && /^test_/.test(CFG.toss);
/* Business details the law requires on a shopping site (전자상거래법 제10조). Fill in before taking real payments. */
var BIZ = {name:'오레 주식회사 (OREH Inc.)', ceo:'정상규', reg:'', mailorder:'', addr:'', email:MAIL_TO, phone:''};
/* Value participation (가치참여) packages: Leon introduces the sponsor for 15 seconds before the story. Example prices. */
var PACKAGES = [{id:'person-30', type:'person', amount:50000, days:30}, {id:'company-30', type:'company', amount:1000000, days:30}];
/* Story film per campaign (the rest show their image) */
var CAMP_VIDEO = {c1:'assets/video/oreh-film.mp4'};
var SAMPLE_SPONSORS = {c1:{type:'company', name:'@leon.sampleName', message:'@leon.sampleMsg', sample:true}, c2:{type:'person', name:'@leon.samplePerson', message:'', sample:true}};
var liveSponsors = {};   /* campaign key -> approved sponsors from the back end */

var deviceId = (function(){
  var id = store.get('oreh.device');
  if (!id || !/^[0-9a-f-]{36}$/.test(id)) {
    var b = new Uint8Array(16); (window.crypto || window.msCrypto).getRandomValues(b);
    b[6] = (b[6] & 15) | 64; b[8] = (b[8] & 63) | 128;
    var h = Array.prototype.map.call(b, function(x){ return (x + 256).toString(16).slice(1); }).join('');
    id = h.slice(0,8) + '-' + h.slice(8,12) + '-' + h.slice(12,16) + '-' + h.slice(16,20) + '-' + h.slice(20);
    store.set('oreh.device', id);
  }
  return id;
})();

function apiHeaders(){
  var h = {'apikey': CFG.anon, 'Content-Type': 'application/json'};
  if (/^eyJ/.test(CFG.anon)) h['Authorization'] = 'Bearer ' + CFG.anon;   // legacy anon key (a JWT)
  return h;
}
function apiCall(path, body){
  return fetch(CFG.api + path, {
    method: body ? 'POST' : 'GET',
    headers: apiHeaders(),
    body: body ? JSON.stringify(body) : undefined
  }).then(function(r){
    return r.json().catch(function(){ return {}; }).then(function(j){
      if (!r.ok) { var e = new Error(j.message || j.error || ('HTTP ' + r.status)); e.code = j.error || j.code || ''; throw e; }
      return j;
    });
  });
}
function storageUrl(bucket, path){ return CFG.api + '/storage/v1/object/public/' + bucket + '/' + path.split('/').map(encodeURIComponent).join('/'); }

/* live numbers: raised, backers, likes, and the approved sponsors Leon introduces */
function daysUntil(end){
  var today = new Date(Date.now() + 9 * 3600 * 1000).toISOString().slice(0, 10);   // KST
  return Math.max(0, Math.round((Date.parse(end + 'T00:00:00Z') - Date.parse(today + 'T00:00:00Z')) / 86400000) + 1);
}
function syncLive(){
  if (!HAS_API) return;
  apiCall('/rest/v1/campaigns?select=id,status,goal_krw,starts_on,ends_on,sponsor_counts').then(function(rows){
    rows.forEach(function(r){ var c = camp(r.id); if (!c) return;
      c.status = r.status === 'live' || r.status === 'soon' ? r.status : 'ended'; c.goal = Number(r.goal_krw) || c.goal;
      c.start = r.starts_on; c.end = r.ends_on; c.daysLeft = daysUntil(r.ends_on); c.sponsorCounts = !!r.sponsor_counts; });
    renderFundList(); if (view === 'project' && cur) renderProject(cur);
  }).catch(function(e){ console.warn('campaigns', e); });
  apiCall('/rest/v1/campaign_stats?select=*').then(function(rows){
    return apiCall('/rest/v1/rpc/my_likes', {p_device: deviceId}).then(function(mine){
      liked = (mine || []).map(function(x){ return typeof x === 'string' ? x : x.my_likes; });
      store.set('oreh.likes', JSON.stringify(liked));
      rows.forEach(function(r){ var c = camp(r.campaign_id); if (!c) return;
        c.raised = r.raised_krw; c.backers = r.backers; c.likes = Math.max(0, r.likes - (isLiked(c) ? 1 : 0)); });
      renderFundList(); if (view === 'project' && cur) renderProject(cur);
    });
  }).catch(function(e){ console.warn('stats', e); });
  apiCall('/rest/v1/public_sponsors?select=*&order=created_at.desc').then(function(rows){
    liveSponsors = {};
    rows.forEach(function(r){
      (liveSponsors[r.campaign_id] = liveSponsors[r.campaign_id] || []).push({
        type: r.sponsor_type, name: r.display_name, message: r.message || '', lang: r.lang,
        logo: r.logo_path ? storageUrl('sponsor-logos', r.logo_path) : '',
        voice: r.voice_path ? storageUrl('leon-voice', r.voice_path) : '',
        video: r.video_path ? storageUrl('sponsor-videos', r.video_path) : ''
      });
    });
    pjMedia.sponsorsLoaded();
  }).catch(function(e){ console.warn('sponsors', e); });
}
function likeRemote(c){
  if (!HAS_API) return;
  apiCall('/rest/v1/rpc/toggle_like', {p_campaign: c.key, p_device: deviceId}).then(function(rows){
    var r = rows && rows[0]; if (!r) return;
    var i = liked.indexOf(c.key);
    if (r.liked && i < 0) liked.push(c.key); if (!r.liked && i > -1) liked.splice(i, 1);
    store.set('oreh.likes', JSON.stringify(liked));
    c.likes = Math.max(0, r.likes - (r.liked ? 1 : 0));
    renderFundList(); if (view === 'project' && cur === c.key) setLikeBtn($('#pjLike'), c);
  }).catch(function(e){ console.warn('like', e); });
}

/* ---------- Leon's 15-second sponsor introduction ----------
   Four lines at 0, 3, 7 and 11.5 seconds. Captions always show; the voice plays when sound is on:
   recorded MP3s when the back end made them (same language), otherwise the browser's speech engine. */
var leon = (function(){
  var CUES = [0, 3000, 7000, 11500], DUR = 15000, SKIP_AFTER = 5000;
  var node = null, sp = null, t0 = 0, raf = 0, step = 0, muted = true, onEnd = null, audios = [], skipBtn = null, bubble = null;
  function txtOf(v){ return v && v.charAt(0) === '@' ? t(v.slice(1)) : (v || ''); }
  function who(s){ var n = txtOf(s.name); return s.type === 'person' ? t('leon.person', {name:n}) : n; }
  function lines(s){
    var n = who(s), m = txtOf(s.message);
    return [t('leon.l1'), t(s.type === 'company' ? 'leon.l2c' : 'leon.l2p', {name:n}), m ? '“' + m + '”' : t('leon.l3'), t('leon.l4', {name:n})];
  }
  function build(host, s){
    var root = el('div', 'leon'); root.setAttribute('role', 'region'); root.setAttribute('aria-label', t('leon.aria', {name: who(s)}));
    root.appendChild(el('div', 'leon__stars'));
    root.appendChild(el('span', 'leon__badge', s.sample ? t('leon.badgeSample') : t(s.type === 'company' ? 'leon.badgeCompany' : 'leon.badgePerson')));
    skipBtn = el('button', 'leon__skip'); skipBtn.type = 'button'; skipBtn.disabled = true;
    skipBtn.addEventListener('click', function(){ if (!skipBtn.disabled) finish(); });
    root.appendChild(skipBtn);
    var av = el('div', 'leon__avatar'); var im = el('img'); im.src = IMGS.leon3d; im.alt = ''; av.appendChild(im); root.appendChild(av);
    root.appendChild(el('span', 'leon__tag', t('leon.virtual')));
    bubble = el('div', 'leon__bubble'); bubble.setAttribute('aria-live', 'polite'); root.appendChild(bubble);
    var card = el('div', 'leon__card');
    if (s.logo) { var lg = el('img', 'leon__logo'); lg.src = s.logo; lg.alt = ''; card.appendChild(lg); }
    else card.appendChild(el('span', 'leon__mono', (txtOf(s.name) || '?').trim().charAt(0).toUpperCase()));
    var w = el('div', 'leon__who');
    w.appendChild(el('span', 'leon__kind', t(s.type === 'company' ? 'leon.kindCompany' : 'leon.kindPerson')));
    w.appendChild(el('span', 'leon__name', txtOf(s.name)));
    card.appendChild(w); root.appendChild(card);
    var hearts = el('div', 'leon__hearts');
    [12, 26, 41, 58, 70, 84].forEach(function(x, i){ var h = el('i'); h.style.left = x + '%'; h.style.animationDelay = (i * 0.28) + 's'; hearts.appendChild(h); });
    root.appendChild(hearts);
    root.appendChild(el('span', 'leon__bar'));
    host.appendChild(root);
    return root;
  }
  function say(i){
    if (muted || !sp) return;
    if (audios[i]) { var a = audios[i]; a.currentTime = 0; var p = a.play(); if (p && p.catch) p.catch(function(){}); return; }
    if (!('speechSynthesis' in window)) return;
    try {
      window.speechSynthesis.cancel();
      var u = new SpeechSynthesisUtterance(lines(sp)[i].replace(/[“”]/g, ''));
      u.lang = {ko:'ko-KR', en:'en-US', zh:'zh-TW'}[lang] || 'ko-KR'; u.rate = 1.05; u.pitch = 1.25;
      u.onstart = function(){ if (node) node.setAttribute('data-talking', ''); };
      u.onend = function(){ if (node) node.removeAttribute('data-talking'); };
      window.speechSynthesis.speak(u);
    } catch(e) {}
  }
  function tick(){
    if (!node) return;
    var e = performance.now() - t0, k = 0;
    for (var i = 0; i < CUES.length; i++) if (e >= CUES[i]) k = i + 1;
    if (k !== step) {
      step = k; node.setAttribute('data-step', String(k));
      bubble.textContent = ''; bubble.appendChild(el('span', 'leon__line', lines(sp)[k - 1]));
      say(k - 1);
    }
    node.style.setProperty('--p', Math.min(100, e / DUR * 100).toFixed(2) + '%');
    var left = Math.ceil((SKIP_AFTER - e) / 1000);
    skipBtn.disabled = left > 0;
    skipBtn.textContent = left > 0 ? t('leon.skipIn', {n:left}) : t('leon.skip');
    if (e >= DUR) { finish(); return; }
    raf = requestAnimationFrame(tick);
  }
  function stop(){
    cancelAnimationFrame(raf); raf = 0;
    try { if ('speechSynthesis' in window) window.speechSynthesis.cancel(); } catch(e) {}
    audios.forEach(function(a){ a.pause(); }); audios = [];
    if (node && node.parentNode) node.parentNode.removeChild(node);
    node = null; sp = null; step = 0;
  }
  function finish(){ var cb = onEnd; stop(); if (cb) cb(); }
  function play(host, s, done){
    stop(); onEnd = done || null; sp = s;
    audios = (s.voice && (!s.lang || s.lang === lang)) ? [1, 2, 3, 4].map(function(i){ var a = new Audio(s.voice + '/' + i + '.mp3'); a.preload = 'auto'; return a; }) : [];
    node = build(host, s); t0 = performance.now(); step = 0; tick();
  }
  function setMuted(m){ muted = m; if (m) { try { window.speechSynthesis.cancel(); } catch(e) {} audios.forEach(function(a){ a.pause(); }); } else if (node && step) say(step - 1); }
  return {play:play, stop:stop, setMuted:setMuted, playing:function(){ return !!node; }};
})();

/* ---------- project media: Leon first (when someone took part), then the story ---------- */
var pjMedia = (function(){
  var muted = true, ad = null, adTimer = 0, introFor = null;
  function sponsorFor(c){
    var list = liveSponsors[c.key];
    if (list && list.length) {
      // license partners with their own Leon introduction film come first
      var films = list.filter(function(s){ return s.video; }), pool = films.length ? films : list;
      return pool[Math.floor(Math.random() * pool.length)];
    }
    return HAS_API ? null : SAMPLE_SPONSORS[c.key] || null;
  }
  function clearAd(){
    clearInterval(adTimer); adTimer = 0;
    if (ad) { ad.remove(); ad = null; }
    var v = $('#pjVideo'); if (v) { v.onended = null; v.onerror = null; }
  }
  // a partner's own Leon introduction film (OREH license partners), labelled as advertising, skippable after 5 s
  function film(c, s){
    var v = $('#pjVideo'), img = $('#pjImg'), box = $('#pjImgBox');
    ad = el('div', 'pjad'); ad.setAttribute('role', 'region'); ad.setAttribute('aria-label', t('leon.aria', {name: s.name}));
    ad.appendChild(el('span', 'pjad__badge', t('leon.badgeCompany')));
    var skip = el('button', 'pjad__skip'); skip.type = 'button'; skip.disabled = true; ad.appendChild(skip);
    ad.appendChild(el('span', 'pjad__tag', t('leon.virtual')));
    box.appendChild(ad);
    var t0 = Date.now();
    function tick(){
      var left = Math.ceil((5000 - (Date.now() - t0)) / 1000);
      skip.disabled = left > 0; skip.textContent = left > 0 ? t('leon.skipIn', {n:left}) : t('leon.skip');
      if (left <= 0) { clearInterval(adTimer); adTimer = 0; }
    }
    tick(); adTimer = setInterval(tick, 250);
    function done(){ clearAd(); story(c); }
    skip.addEventListener('click', function(){ if (!skip.disabled) done(); });
    v.onended = done; v.onerror = done;
    v.loop = false; v.src = s.video; v.hidden = false; img.hidden = true; v.muted = muted;
    var p = v.play(); if (p && p.catch) p.catch(function(){});
  }
  function story(c){
    var v = $('#pjVideo'), img = $('#pjImg');
    v.onended = null; v.onerror = null;
    if (CAMP_VIDEO[c.key]) {
      if (v.getAttribute('src') !== CAMP_VIDEO[c.key]) v.src = CAMP_VIDEO[c.key];
      v.hidden = false; img.hidden = true; v.muted = muted; v.loop = true;
      var p = v.play(); if (p && p.catch) p.catch(function(){});
    } else { v.hidden = true; v.pause(); img.hidden = false; }
    $('#pjReplay').hidden = !sponsorFor(c);
  }
  function start(c){
    stop(); var s = sponsorFor(c), box = $('#pjImgBox');
    introFor = s ? c.key : null;
    $('#pjReplay').hidden = true;
    if (s && s.video) film(c, s);
    else if (s) { $('#pjImg').hidden = false; leon.setMuted(muted); leon.play(box, s, function(){ story(c); }); }
    else story(c);
  }
  function preview(s){ stop(); leon.setMuted(muted); leon.play($('#pjImgBox'), s, function(){ var c = camp(cur); if (c) story(c); }); }
  function stop(){ leon.stop(); clearAd(); var v = $('#pjVideo'); if (v) v.pause(); }
  function sound(){
    muted = !muted; leon.setMuted(muted); var v = $('#pjVideo'); if (v) v.muted = muted;
    var b = $('#pjSound'); b.setAttribute('aria-pressed', String(!muted)); b.setAttribute('data-i18n', muted ? 'hero.sound.on' : 'hero.sound.off'); b.textContent = t(muted ? 'hero.sound.on' : 'hero.sound.off');
  }
  // the sponsor list arrives after the page opens: start the introduction then, once per project visit
  function sponsorsLoaded(){
    var c = view === 'project' && cur ? camp(cur) : null;
    if (c && introFor !== c.key && sponsorFor(c)) start(c);
  }
  return {start:start, stop:stop, preview:preview, sound:sound, sponsorsLoaded:sponsorsLoaded};
})();

