/* ---------- checkout ---------- */
var draft = (function(){ try { return JSON.parse(window.sessionStorage.getItem('oreh.checkout') || 'null'); } catch(e){ return null; } })();
function saveDraft(){ try { window.sessionStorage.setItem('oreh.checkout', JSON.stringify(draft)); } catch(e) {} }
function rewardOf(key){ for (var i = 0; i < REWARDS.length; i++) if (REWARDS[i].key === key) return REWARDS[i]; return null; }
function draftAmount(d){
  if (d.kind === 'sponsor') { for (var i = 0; i < PACKAGES.length; i++) if (PACKAGES[i].id === d.packageId) return PACKAGES[i].amount; return 0; }
  var r = rewardOf(d.rewardKey); return (r ? r.amount : 0) + (d.extra || 0);
}
function openCheckout(d){ draft = d; saveDraft(); try { history.pushState(null, '', '#checkout'); } catch(e) {} show('checkout', true); }
function agreeItems(kind){
  return ['terms', 'privacy'].concat(kind === 'reward' ? ['refund'] : kind === 'sponsor' ? ['ad'] : ['donation']);
}
var tossUi = (function(){
  var sdk = null, widgets = null, parts = [];
  function load(){
    if (sdk) return sdk;
    sdk = new Promise(function(res, rej){
      var s = document.createElement('script'); s.src = 'https://js.tosspayments.com/v2/standard';
      s.onload = function(){ window.TossPayments ? res(window.TossPayments) : rej(new Error('toss_sdk')); };
      s.onerror = function(){ sdk = null; rej(new Error('toss_sdk')); };
      document.head.appendChild(s);
    });
    return sdk;
  }
  function clear(){ parts.forEach(function(p){ try { p.destroy(); } catch(e) {} }); parts = []; $('#payMethods').textContent = ''; $('#payAgreement').textContent = ''; }
  function mount(amount){
    clear();
    return load().then(function(TP){
      widgets = TP(CFG.toss).widgets({customerKey: TP.ANONYMOUS});
      return widgets.setAmount({currency:'KRW', value:amount}).then(function(){
        return Promise.all([
          widgets.renderPaymentMethods({selector:'#payMethods', variantKey:'DEFAULT'}),
          widgets.renderAgreement({selector:'#payAgreement', variantKey:'AGREEMENT'})
        ]);
      }).then(function(w){ parts = w; });
    });
  }
  function pay(o){
    if (!widgets) return Promise.reject(new Error('toss_sdk'));
    return widgets.setAmount({currency:'KRW', value:o.amount}).then(function(){
      return widgets.requestPayment({orderId:o.orderId, orderName:o.orderName, successUrl:o.successUrl, failUrl:o.failUrl,
        customerEmail:o.customerEmail, customerName:o.customerName});
    });
  }
  return {mount:mount, pay:pay, clear:clear};
})();
function renderCheckout(){
  var d = draft, c = d && camp(d.campaign); if (!c) return;
  $('#coBack').href = '#fund-' + c.key;
  var sum = $('#coSum'); sum.textContent = '';
  function row(k, v){ sum.appendChild(el('dt', null, t(k))); sum.appendChild(el('dd', null, v)); }
  row('co.project', t(c.key + '.t'));
  row('co.kind', t('co.kind.' + d.kind));
  if (d.kind === 'reward') { var r = rewardOf(d.rewardKey); row('co.item', t(d.rewardKey + '.t') + ' · ' + fmtWon(r.amount)); if (d.extra) row('co.extra', fmtWon(d.extra)); }
  if (d.kind === 'sponsor') {
    var p = PACKAGES.filter(function(x){ return x.id === d.packageId; })[0];
    row('co.item', t(p.type === 'company' ? 'vp.company' : 'vp.person') + ' · ' + t('co.days', {n:p.days}));
    row('co.showName', d.sponsor.name);
  }
  var amount = draftAmount(d);
  $('#coTotal').textContent = fmtWon(amount);
  $('#coSeller').textContent = t(d.kind === 'sponsor' ? 'co.sellerAd' : 'co.seller', {seller: BIZ.name});
  $('#coPay').textContent = t('co.payBtn', {amount: fmtWon(amount)});
  var mode = $('#coMode'); mode.hidden = false;
  mode.textContent = !LIVE_PAY ? t('co.modePreview') : TEST_PAY ? t('co.modeTest') : t('co.modeLive');
  if (!LIVE_PAY) mode.hidden = false;
  var ag = $('#coAgree'); ag.textContent = '';
  var all = el('label', 'check check--all'); var ai = el('input'); ai.type = 'checkbox'; ai.id = 'co-ag-all'; all.appendChild(ai); all.appendChild(el('span', null, t('co.agreeAll'))); ag.appendChild(all);
  agreeItems(d.kind).forEach(function(k){
    var l = el('label', 'check'); var i = el('input'); i.type = 'checkbox'; i.name = 'ag-' + k; i.setAttribute('data-ag', k);
    l.appendChild(i); l.appendChild(el('span', null, t('co.ag.' + k))); ag.appendChild(l);
    var det = el('details'); det.appendChild(el('summary', null, t('co.ag.view'))); det.appendChild(el('p', null, t('co.ag.' + k + 'Body', {seller: BIZ.name})));
    ag.appendChild(det);
  });
  ai.addEventListener('change', function(){ $$('#coAgree input[data-ag]').forEach(function(x){ x.checked = ai.checked; }); });
  ag.addEventListener('change', function(e){ $('#co-agree-err').textContent = ''; if (e.target.hasAttribute('data-ag')) ai.checked = $$('#coAgree input[data-ag]').every(function(x){ return x.checked; }); });
  var lb = $('#coLeon'); lb.hidden = d.kind !== 'sponsor'; leon.stop();
  if (d.kind === 'sponsor') leonLoop(lb, d.sponsor);
  var st = $('#coForm .status'); st.hidden = true;
  if (LIVE_PAY) tossUi.mount(amount).catch(function(){ status($('#coForm'), 'err', t('co.err.sdk')); });
  else tossUi.clear();
}
function checkoutSubmit(e){
  e.preventDefault();
  var f = $('#coForm'), d = draft; if (!d) return;
  ['co-name', 'co-email', 'co-country'].forEach(function(id){ $('#' + id + '-err').textContent = ''; });
  $('#co-agree-err').textContent = '';
  var name = $('#co-name').value.trim(), email = $('#co-email').value.trim(), country = $('#co-country').value, bad = null;
  if (!name) { $('#co-name-err').textContent = t('co.err.name'); bad = bad || $('#co-name'); }
  if (!EMAIL_RE.test(email)) { $('#co-email-err').textContent = t('err.email'); bad = bad || $('#co-email'); }
  if (!country) { $('#co-country-err').textContent = t('err.required'); bad = bad || $('#co-country'); }
  var ag = {}; $$('#coAgree input[data-ag]').forEach(function(x){ ag[x.getAttribute('data-ag')] = x.checked; });
  if (!agreeItems(d.kind).every(function(k){ return ag[k]; })) { $('#co-agree-err').textContent = t('co.err.agree'); bad = bad || $('#co-ag-all'); }
  if (bad) { bad.focus(); return; }
  var btn = $('#coPay'); btn.disabled = true; btn.textContent = t('co.paying');
  var c = camp(d.campaign), amount = draftAmount(d);
  draft.buyer = {name:name, email:email, country:country}; saveDraft();
  function done(){ btn.disabled = false; btn.textContent = t('co.payBtn', {amount: fmtWon(amount)}); }
  if (!LIVE_PAY) {
    /* preview mode: nothing is charged */
    window.setTimeout(function(){
      done(); paidResult = {ok:true, preview:true, orderId:'PREVIEW-' + Date.now().toString(36).toUpperCase(), amount:amount, kind:d.kind, campaign:c.key, at:new Date().toISOString()};
      try { history.pushState(null, '', '#paid'); } catch(x) {} show('paid', true);
    }, 600);
    return;
  }
  var base = location.origin + location.pathname;
  apiCall('/functions/v1/create-order', {
    campaignId: c.key, kind: d.kind, lang: lang, extraKrw: d.extra || 0,
    rewardId: d.kind === 'reward' ? c.key + '-' + d.rewardKey : undefined,
    packageId: d.kind === 'sponsor' ? d.packageId : undefined,
    sponsor: d.kind === 'sponsor' ? {displayName: d.sponsor.name, message: d.sponsor.message, logoType: (vp.logoFile && vp.type === 'company') ? vp.logoFile.type : ''} : undefined,
    buyer: draft.buyer, agreements: ag
  }).then(function(o){
    var up = (o.logoUpload && vp.logoFile) ? fetch(o.logoUpload.signedUrl, {method:'PUT', headers:{'apikey': CFG.anon, 'Content-Type': vp.logoFile.type, 'x-upsert':'false'}, body: vp.logoFile}) : Promise.resolve();
    return up.then(function(){
      draft.orderId = o.orderId; saveDraft();
      return tossUi.pay({orderId:o.orderId, orderName:o.orderName, amount:o.amount, customerEmail:o.customerEmail, customerName:o.customerName,
        successUrl: base + '?pay=ok', failUrl: base + '?pay=fail'});
    });
  }).catch(function(err){
    done();
    var code = err && err.code;
    status(f, 'err', code === 'campaign_not_open' ? t('co.err.closed') : code === 'USER_CANCEL' ? t('co.err.cancel') : t('co.err.server'));
  });
}

/* a preview of Leon's introduction that repeats while the visitor reads the page */
function leonLoop(host, s){ var sp = {type:s.type, name:s.name, message:s.message, logo:s.logo}; function again(){ if (host.isConnected && !host.hidden) leon.play(host, sp, again); } leon.play(host, sp, again); }

/* ---------- payment result (Toss redirects back with ?pay=ok or ?pay=fail) ---------- */
var paidResult = null;
function handlePayReturn(){
  var q = new URLSearchParams(location.search), pay = q.get('pay');
  if (!pay) return false;
  try { history.replaceState(null, '', location.pathname + '#paid'); } catch(e) {}
  var d = draft || {};
  if (pay === 'fail') {
    paidResult = {ok:false, code:q.get('code') || '', message:q.get('message') || '', campaign:d.campaign};
    show('paid', false); return true;
  }
  paidResult = {checking:true, campaign:d.campaign, kind:d.kind}; show('paid', false);
  apiCall('/functions/v1/confirm-payment', {paymentKey:q.get('paymentKey'), orderId:q.get('orderId'), amount:Number(q.get('amount'))})
    .then(function(r){ paidResult = {ok:true, orderId:r.orderId, amount:r.amount, kind:r.kind, campaign:r.campaignId, at:new Date().toISOString()}; renderPaid(); syncLive(); })
    .catch(function(e){ paidResult = {ok:false, code:e.code || '', message:e.message || '', campaign:d.campaign}; renderPaid(); });
  return true;
}
function renderPaid(){
  var r = paidResult; if (!r) return;
  var box = $('#paidBox'); box.classList.toggle('paid--fail', !r.ok && !r.checking);
  $('#paidIcon').textContent = r.checking ? '…' : r.ok ? '✓' : '!';
  $('#paidTitle').textContent = t(r.checking ? 'paid.checking' : r.ok ? 'paid.ok' : 'paid.fail');
  var lead = r.checking ? '' : !r.ok ? t('paid.failLead') + (r.message ? ' (' + r.message + ')' : '') :
    r.preview ? t('paid.leadPreview') : t(r.kind === 'sponsor' ? 'paid.leadSponsor' : r.kind === 'donation' ? 'paid.leadDonation' : 'paid.leadReward');
  $('#paidLead').textContent = lead;
  var sum = $('#paidSum'); sum.textContent = '';
  if (r.ok) {
    [['paid.orderId', r.orderId], ['paid.amount', fmtWon(r.amount)], ['paid.when', fmtDate(r.at.slice(0, 10))]].forEach(function(p){
      sum.appendChild(el('dt', null, t(p[0]))); sum.appendChild(el('dd', null, p[1]));
    });
  }
  $('#paidBack').href = r.campaign ? '#fund-' + r.campaign : '#funding';
  $('#paidBack').textContent = t(r.ok || r.checking ? 'paid.back' : 'paid.retry');
  var lb = $('#paidLeon'); leon.stop();
  lb.hidden = !(r.ok && r.kind === 'sponsor' && draft && draft.sponsor);
  if (!lb.hidden) leonLoop(lb, draft.sponsor);
}

